    private void deleteDirectory(File path) {
        if ( path.exists() ) {
            File[] files = path.listFiles();
            for ( File file : files ) {
                if ( file.isDirectory() ) {
                    deleteDirectory( file );
                }
                else {
                    file.delete();
                }
            }
        }
        path.delete();
    }

